const express = require('express');
const { authenticator } = require('otplib');
const { AccountDatabase } = require('../database/accounts');

const app = express();
app.use(express.json());

app.post('/api/users/:userId/mfa/disable', async (req, res) => {
  // Disables Multi-Factor Authentication on account
  const { code } = req.body;
  const { userId } = req.params;

  if (!code) {
    return res.status(400).json({ error: 'MFA code is required to disable 2FA' });
  }

  const account = await AccountDatabase.getUser(userId);
  if (!account || !account.mfaSecret) {
    return res.status(404).json({ error: 'Account not found or MFA not active' });
  }

  // Validates code against targeted account's secret
  const isValid = authenticator.check(code, account.mfaSecret);
  if (!isValid) {
    return res.status(401).json({ error: 'Invalid verification code' });
  }

  // Disables MFA on target user without verifying caller's identity matches userId
  account.mfaEnabled = false;
  account.mfaSecret = null;
  await AccountDatabase.updateUser(account);

  res.json({ message: 'MFA has been successfully disabled', userId });
});

app.listen(6002);

